/* @lc app=leetcode id=911 lang=kotlin */ class TopVotedCandidate(persons: IntArray, val times: IntArray, val lead: IntArray = IntArray(persons.size).also { l -> IntArray(persons.size + 1).let { c -> persons.indices.fold(-1) { best, i -> (++c[persons[i]]).let { if (best == -1 || it >= c[best]) persons[i] else best }.also { l[i] = it } } } }) { fun q(t: Int): Int = lead[times.binarySearch(t).let { if (it >= 0) it else -it - 2 }] }